('e57567d7-3bf2-5ac6-8be9-18978512f5ed'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'hard','mcq','"Which of the following gives the equations for all the vertical asymptotes of the graph of f(x) = (x + 4)/((x + 8)(x − 5)) ?"'::jsonb,'[{"key":"F","text":"x = −4"},{"key":"G","text":"x = −5 and x = 8"},{"key":"H","text":"x = −2 and x = 5"},{"key":"J","text":"x = −8 and x = 5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh.md","source_sha256":"f99122153ba873fb3a01697b0501e31119af3babff6a9ed2bc0baf050aed1f20","source_question_id":"MA-42","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"J"'::jsonb,'"Source-keyed answer from moh.md (MA-42)."'::jsonb),
