('4bbe9957-1eca-5972-ba05-1708451da660'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"The hand on the circular clock in the figure below measures 10 cm.\n[Figure: Circular clock with a 10 cm hand pointing from the center to the 12; dashed hand pointing to the 3.]\nWhich of the following is closest to the distance that the tip of the hand travels as it moves from the 12 to the 3?"'::jsonb,'[{"key":"A","text":"79 cm"},{"key":"B","text":"21 cm"},{"key":"C","text":"63 cm"},{"key":"D","text":"16 cm"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"moh_geo.md","source_sha256":"fd550cf9acb0c34c08b3bebd88f0b67714179fd7b1d4644f694d4388df535983","source_question_id":"MG-21","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/MG-21.png","image_alt":"Original graph, diagram, or table for MG-21","visual_verified":true}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from moh_geo.md (MG-21)."'::jsonb),
